import{_ as s,C as d,o,c as r,j as a,a as l,E as n,a2 as p}from"./chunks/framework.DGvnA5EY.js";const i="/workbuddy-guide/assets/24-hei-multiagent.CUFqvl-3.png",q=JSON.parse('{"title":"第 24 章 如何进行多 Agent 系统设计","description":"> 内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利） 一个对话用久了，你会撞上三堵墙：上下文太长它开始忘事、角色太多它开始串味、 活太多它只能排队干。这三堵墙，就是多 Agent 系统存在的理由。","frontmatter":{"title":"第 24 章 如何进行多 Agent 系统设计"},"headers":[],"relativePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 24 章 如何进行多 Agent 系统设计/index.md","filePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 24 章 如何进行多 Agent 系统设计/index.md","lastUpdated":1791629861000}'),g={name:"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 24 章 如何进行多 Agent 系统设计/index.md"};function h(u,t,b,c,A,m){const e=d("Paywall");return o(),r("div",null,[t[0]||(t[0]=a("h1",{id:"第-24-章-如何进行多-agent-系统设计",tabindex:"-1"},[l("第 24 章 如何进行多 Agent 系统设计 "),a("a",{class:"header-anchor",href:"#第-24-章-如何进行多-agent-系统设计","aria-label":'Permalink to "第 24 章 如何进行多 Agent 系统设计"'},"​")],-1)),t[1]||(t[1]=a("blockquote",null,[a("p",null,"内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利）")],-1)),n(e,{part:"3",variant:"banner"}),t[2]||(t[2]=p('<p>一个对话用久了，你会撞上三堵墙：<strong>上下文太长它开始忘事、角色太多它开始串味、 活太多它只能排队干</strong>。这三堵墙，就是多 Agent 系统存在的理由。</p><p>这一章用人话讲清多 Agent 的原理，并带你搭一条真实的内容生产流水线。 学完你就明白：所谓多 Agent，不是玄学，就是<strong>给 AI 团队定编制、定岗位、定交接单</strong>。</p><p><img src="'+i+`" alt="一只小黑像指挥家一样指挥一排色块整齐行动" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解本章主题，与实际软件界面无关。</em></p><h2 id="一、先想清楚-你需要多-agent-吗" tabindex="-1">一、先想清楚：你需要多 Agent 吗 <a class="header-anchor" href="#一、先想清楚-你需要多-agent-吗" aria-label="Permalink to &quot;一、先想清楚：你需要多 Agent 吗&quot;">​</a></h2><table tabindex="0"><thead><tr><th>信号</th><th>说明</th><th>解法</th></tr></thead><tbody><tr><td>对话越长越忘事</td><td>上下文被塞满，早期要求被稀释</td><td>把独立任务拆给子 Agent（干净的上下文）</td></tr><tr><td>一会儿当写手一会儿当审稿</td><td>角色混杂，输出风格摇摆</td><td>一个角色一个 Agent，各司其职</td></tr><tr><td>几件互不依赖的活要干</td><td>单线排队浪费时间</td><td>并行派发，同时开工</td></tr><tr><td>需要不同&quot;专业工具&quot;</td><td>主对话工具太杂容易用错</td><td>子 Agent 只配它需要的工具</td></tr></tbody></table><p><strong>反向信号</strong>：任务 10 分钟就能干完、或者步骤之间强依赖你逐步拍板——别拆， 单对话更省事。多 Agent 是组织成本，不是免费午餐。</p><h2 id="二、三个核心概念-人话版" tabindex="-1">二、三个核心概念（人话版） <a class="header-anchor" href="#二、三个核心概念-人话版" aria-label="Permalink to &quot;二、三个核心概念（人话版）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>类比</th><th>关键特性</th></tr></thead><tbody><tr><td>主对话</td><td>项目经理</td><td>只有它一直&quot;记得&quot;全局；负责拆活、派活、验收</td></tr><tr><td>子 Agent（subagent）</td><td>外包专才</td><td>干完就解散；<strong>看不到你和主对话的聊天记录</strong>，只看到你派活时写的任务书</td></tr><tr><td>专家包（Expert）</td><td>挂名顾问</td><td>带着成熟方法论上岗，适合单点请教；不能和子 Agent 混用</td></tr></tbody></table><blockquote><p><strong>最重要的一个事实</strong>：子 Agent 是&quot;新人入职&quot;。它不知道你之前的任何对话—— 你以为写了背景，其实它根本看不见。所以派活的任务书必须<strong>自包含</strong>： 目标、材料路径、格式要求、验收标准，一样不能少。</p></blockquote><h2 id="三、三种经典架构" tabindex="-1">三、三种经典架构 <a class="header-anchor" href="#三、三种经典架构" aria-label="Permalink to &quot;三、三种经典架构&quot;">​</a></h2><h3 id="架构-1-串行流水线-上游-→-下游" tabindex="-1">架构 1｜串行流水线（上游 → 下游） <a class="header-anchor" href="#架构-1-串行流水线-上游-→-下游" aria-label="Permalink to &quot;架构 1｜串行流水线（上游 → 下游）&quot;">​</a></h3><p>适合：内容生产、翻译 + 润色、报告生成这类<strong>顺序依赖</strong>的活。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>选题 Agent → 写作 Agent → 审稿 Agent → 排版 Agent</span></span>
<span class="line"><span>   （每道工序产出一个文件，下一道只读上游的文件开工）</span></span></code></pre></div><p>要点：<strong>交接靠文件，不靠记忆</strong>。每道工序把产物写到磁盘，下一道从磁盘读。</p><h3 id="架构-2-并行地图归并-分头查-→-汇总" tabindex="-1">架构 2｜并行地图归并（分头查 → 汇总） <a class="header-anchor" href="#架构-2-并行地图归并-分头查-→-汇总" aria-label="Permalink to &quot;架构 2｜并行地图归并（分头查 → 汇总）&quot;">​</a></h3><p>适合：调研、竞品对比、多方案探索这类<strong>互不依赖</strong>的活。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主对话 ──┬─→ 调研 Agent A（渠道一）──┐</span></span>
<span class="line"><span>         ├─→ 调研 Agent B（渠道二）──┼─→ 主对话汇总成对比报告</span></span>
<span class="line"><span>         └─→ 调研 Agent C（渠道三）──┘</span></span></code></pre></div><p>要点：三个任务书<strong>格式统一</strong>（同样的输出模板），汇总才不痛苦。</p><h3 id="架构-3-主从协作-派活-验收循环" tabindex="-1">架构 3｜主从协作（派活 + 验收循环） <a class="header-anchor" href="#架构-3-主从协作-派活-验收循环" aria-label="Permalink to &quot;架构 3｜主从协作（派活 + 验收循环）&quot;">​</a></h3><p>适合：长期项目，主对话当 PM，子 Agent 当执行层。</p><p>要点：主对话负责<strong>拆活、派活、验收、记账</strong>（用共享任务清单跟踪状态）， 不亲自干活；子 Agent 交付后由主对话检查，不合格打回重做。</p>`,22)),n(e,{part:"3"}),t[3]||(t[3]=a("p",null,[a("em",null,"—— 以上试读到此为止。第三篇共 4 章，完整版（飞书文档）包含全部实操内容。——")],-1))])}const x=s(g,[["render",h]]);export{q as __pageData,x as default};
